mapper.select:
SELECT interruptible FROM device_method
 WHERE tenant_id = #{param1} AND device_id = #{param2} AND method = #{param3}
 LIMIT 1

mapper.update:
UPDATE device_access
   SET state = #{param3}, state_checked_at = now()
 WHERE tenant_id = #{param1} AND id = #{param2}

UPDATE position_state
   SET reserved_until = NULL, reserved_by_run = NULL, updated_at = now()
 WHERE tenant_id = #{param1} AND resource_id = #{param2} AND reserved_by_run = #{param3}

UPDATE position_state
   SET reserved_until = NULL, reserved_by_run = NULL, updated_at = now()
 WHERE tenant_id = #{param1} AND reserved_by_run = #{param2}

UPDATE position_state
   SET plate_id = NULL, occupied_since = NULL, occupied_by_run = NULL,
       updated_at = now()
 WHERE tenant_id = #{param1} AND resource_id = #{param2}
   AND occupied_by_run = #{param3}

mapper.select:
SELECT kind::text FROM resource_node
 WHERE tenant_id = #{param1} AND id = #{param2}
   AND kind IN ('incubator', 'storage', 'transfer_point')

mapper.update:
UPDATE device_state
   SET current_run_id = NULL, current_method = NULL,
       status = CASE WHEN last_error IS NULL THEN 'idle' ELSE status END,
       updated_at = now()
 WHERE tenant_id = #{tenantId} AND resource_id = #{resourceId}
   AND current_run_id = #{runId}
